// 1. Catch synchronous runtime crashes
window.addEventListener('error', (event) => {
  console.error("Global Sync Crash Detected:", event.message, event.filename, event.lineno);
  // e.g., sendToSentry(event.error);
});

// 2. Catch forgotten Promise rejections
window.addEventListener('unhandledrejection', (event) => {
  console.error("You forgot a .catch() on a Promise! Reason:", event.reason);
});

